from pathlib import Path

p=Path('DEVELOPMENT_STATUS.md')
s=p.read_text(encoding='utf-8')
old="v91で原作EXE4の被弾後ショートインビジを参考に、通常被弾が成立した直後から `2秒` の被弾後無敵を `player-damage-system.js` へ追加した。無敵中は `resolvePointHit()` / `resolveRangeHit()` が `INVINCIBLE` として追加ダメージを不成立にし、点攻撃のテスト弾はプレイヤーへ重なっても命中扱いにならず通過する。見た目は `css/player-damage.css` の `opacity` だけを使った段階点滅とし、負荷の大きい `filter` やglowは使用しない。撃破に至る被弾では無敵を開始しない。のけぞり・ノックバックは今回含めない。CUSTOM等で戦闘を一時停止している間に無敵時間自体を停止するかは未確定のため、v91実装では `performance.now()` 基準の実時間で管理する。v91は2秒間の点滅、連続被弾防止、無敵中の弾通過を実機確認待ち。"
new=old.replace("v91は2秒間の点滅、連続被弾防止、無敵中の弾通過を実機確認待ち。","実機確認で、被弾後に約2秒間プレイヤーが点滅する表示に問題がないことを確認済み。連続被弾防止と無敵中の弾通過は共通被ダメージ経路上で実装済みだが、現テスト敵は次弾までの間隔が長く実機再現しづらいため、高頻度攻撃・複数敵攻撃を導入した段階で再確認する。")
if old not in s:
    raise SystemExit('v91 paragraph not found')
s=s.replace(old,new,1)
old2="## 次フェーズ: v91 被弾後無敵 実機確認\n\nv82〜v85で左上HP表示とココロウィンドウ、v86で初期HP100、v87〜v88で被ダメージ経路とテスト敵攻撃、v89でキャノン非貫通、v90でリカバリー10の実HP回復まで実機確認済み。v91ではEXE4を参考に被弾成功後2秒のショートインビジ相当と、軽量な半透明点滅を接続した。次は実機で点滅時間、連続被弾防止、無敵中の弾通過、操作負荷に問題がないことを確認する。\n\n優先対象は以下。\n\n1. 敵弾を受けた直後にプレイヤーが約2秒間点滅することを確認する。\n2. 点滅中に別の通常敵弾が重なってもHPが追加で減らないことを確認する。\n3. 点滅中の敵弾がプレイヤーで消えず、そのまま通過することを確認する。\n4. 点滅中の移動・旋回・B攻撃・CUSTOMゲージ表示で負荷退行がないことを確認する。\n5. v91確認後、のけぞり・ノックバックと撃破処理へ進む。\n6. 敵AI・Wave進行へ段階的に進める。"
new2="## 次フェーズ: のけぞり・ノックバック\n\nv82〜v85で左上HP表示とココロウィンドウ、v86で初期HP100、v87〜v88で被ダメージ経路とテスト敵攻撃、v89でキャノン非貫通、v90でリカバリー10の実HP回復まで実機確認済み。v91では被弾成功後2秒のショートインビジ相当を実装し、被弾後約2秒の軽量点滅表示を実機確認済み。連続被弾防止と無敵中の弾通過は実装済みで、高頻度攻撃・複数敵攻撃を導入した段階で追加実機確認する。次は被弾時ののけぞり・ノックバックを設計する。\n\n優先対象は以下。\n\n1. のけぞり中の操作可否・攻撃可否を確定する。\n2. ノックバック方向・距離・時間を確定する。\n3. フィールド端や将来の侵入不可地形を越えない移動処理として実装する。\n4. v91の被弾後無敵と開始タイミングを整合させる。\n5. その後、HP0時の撃破処理へ進む。\n6. 高頻度攻撃・複数敵攻撃の導入時にv91の連続被弾防止と弾通過を再確認する。\n7. 敵AI・Wave進行へ段階的に進める。"
if old2 not in s:
    raise SystemExit('next phase block not found')
s=s.replace(old2,new2,1)
p.write_text(s,encoding='utf-8')
